<?php
/**
 * Customizer finalization.
 *
 * Applies detailed-mode visibility and stable control ordering after modules register.
 *
 * @package CreceWebLumen
 */

namespace CreceWeb\Lumen;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

